Here's a simple TypeScript debounce function:

```typescript
function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout | null = null;

  const debounced = (...args: Parameters<T>) => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      fn(...args);
      timeoutId = null;
    }, wait);
  };

  // Clean up on unmount if needed (e.g., for React)
  return {
    ...debounced,
    cancel: () => {
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
    }
  };
}
```

Usage:

```typescript
const handleClick = () => console.log('Button clicked');

const debouncedClick = debounce(handleClick, 300);

// Calling debouncedClick multiple times within 300ms will only trigger
// the last call after the 300ms delay
debouncedClick(); // No output yet
debouncedClick(); // No output yet
debouncedClick(); // Logs "Button clicked" after 300ms
```

The function returns an object with the debounced function and a `cancel` method to clear any pending timeout. It works with any function signature and handles multiple calls within the wait period by canceling the previous timeout.

